'use strict';

// MODULES //

var tape = require( 'tape' );
var validate = require( './../lib/validate.js' );
var lower = require( './../lib/lower_jupyterlite_javascript.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof lower, 'function', 'main export is a function' );
	t.end();
});

tape( 'the lowering function rewrites only selected declaration ranges', function test( t ) {
	var source = "// keep\nvar ndarray = require( '@stdlib/ndarray/ctor' );\n// keep";
	var result = lower( source, validate(), 'worker' );

	t.strictEqual( result.ok, true, 'returns success' );
	t.strictEqual( result.code, "// keep\nimport ndarray from 'https://cdn.jsdelivr.net/gh/stdlib-js/ndarray-ctor@esm/index.mjs';\n// keep", 'preserves surrounding source exactly' );
	t.deepEqual( result.transforms[ 0 ].range, [ 8, 56 ], 'records the semantic UTF-16 range' );
	t.end();
});

tape( 'the lowering function supports verified authored default imports', function test( t ) {
	var result = lower( "import abs from '@stdlib/math/base/special/abs';", validate(), 'worker' );

	t.strictEqual( result.ok, true, 'returns success' );
	t.strictEqual( result.code, "import abs from 'https://cdn.jsdelivr.net/gh/stdlib-js/math-base-special-abs@esm/index.mjs';", 'rewrites only the module source literal' );
	t.strictEqual( result.transforms[ 0 ].kind, 'module-specifier-to-url', 'records the transform kind' );
	t.end();
});

tape( 'the lowering function atomically rejects unsafe CommonJS bindings', function test( t ) {
	var options = validate({
		'mode': 'permissive'
	});
	var result;
	var cases = [
		[ "var abs = require( '@stdlib/math/base/special/abs' );\nabs = noop;", 'mutable-import-binding' ],
		[ "abs;\nvar abs = require( '@stdlib/math/base/special/abs' );", 'binding-read-before-import' ],
		[ "var abs = require( '@stdlib/math/base/special/abs' ), x = 1;", 'residual-require' ],
		[ "var require = noop;\nvar abs = require( '@stdlib/math/base/special/abs' );", 'shadowed-require' ],
		[ "var fs = require( 'fs' );", 'unsupported-node-builtin' ],
		[ "import abs from '@stdlib/math/base/special/abs';\nabs = noop;", 'mutable-import-binding' ]
	];
	var i;

	for ( i = 0; i < cases.length; i++ ) {
		result = lower( cases[ i ][ 0 ], options, 'worker' );
		t.strictEqual( result.ok, false, 'rejects unsafe case '+i );
		t.strictEqual( result.code, cases[ i ][ 1 ], 'returns expected code '+i );
	}
	t.end();
});

tape( 'the lowering function performs scope-aware runtime global checks', function test( t ) {
	var globals = [
		'document',
		'HTMLElement',
		'customElements',
		'localStorage',
		'requestAnimationFrame'
	];
	var options = validate();
	var result;
	var i;

	for ( i = 0; i < globals.length; i++ ) {
		result = lower( globals[ i ]+';', options, 'worker' );
		t.strictEqual( result.code, 'unsupported-worker-global', 'rejects free worker global '+globals[ i ] );
		result = lower( globals[ i ]+';', options, 'iframe' );
		t.strictEqual( result.ok, true, 'allows iframe global '+globals[ i ] );
	}
	result = lower( 'function f( document ) { return document.body; }', options, 'worker' );
	t.strictEqual( result.ok, true, 'allows a shadowed DOM name' );
	result = lower( 'process.cwd();', options, 'iframe' );
	t.strictEqual( result.code, 'unsupported-node-global', 'rejects a free Node global in either runtime' );
	t.end();
});
